// Fast lookup by normalized title
const pricingByNormalizedTitle = new Map<string, ProgramPricing>();
// Fast lookup by common search keywords/tokens
const pricingList = PROGRAM_PRICING_LIST;

for (const item of pricingList) {
  const key = item.title.toLowerCase().replace(/[^a-z0-9]+/g, '');
  pricingByNormalizedTitle.set(key, item);
}

export function getProgramPricing(titleOrSlug: string): ProgramPricing {
  if (!titleOrSlug) {
    return {
      title: '',
      days: 3,
      duration: '3 Hari',
      price: 'Rp 4.500.000',
      priceNumber: 4500000,
    };
  }

  const raw = titleOrSlug.toLowerCase();
  const normalized = raw.replace(/[^a-z0-9]+/g, '');

  // 1. Exact match by normalized string
  if (pricingByNormalizedTitle.has(normalized)) {
    return pricingByNormalizedTitle.get(normalized)!;
  }

  // 2. Fuzzy match against program titles
  for (const item of pricingList) {
    const itemNorm = item.title.toLowerCase().replace(/[^a-z0-9]+/g, '');
    if (normalized.includes(itemNorm) || itemNorm.includes(normalized)) {
      return item;
    }
  }

  // 3. Keyword-based matching
  if (raw.includes('ahli-k3-umum') || raw.includes('ahli k3 umum')) {
    return pricingList[0]; // Ahli K3 Umum Rp 6.000.000
  }
  if (raw.includes('lead-auditor') || raw.includes('lead auditor')) {
    return pricingList[2]; // Lead Auditor Rp 6.500.000
  }
  if (raw.includes('auditor-smk3') || raw.includes('auditor smk3')) {
    return pricingList[1]; // Auditor SMK3 Rp 5.000.000
  }
  if (raw.includes('p3k-di-tempat-kerja') || raw.includes('petugas p3k')) {
    return pricingList[270] || pricingList[1]; // Petugas P3K
  }
  if (raw.includes('teknisi-k3-listrik') || raw.includes('teknisi k3 listrik')) {
    return pricingList[61]; // Teknisi Listrik Rp 7.000.000
  }
  if (raw.includes('tkpk-1') || raw.includes('ketinggian tingkat 1')) {
    return pricingList[242]; // TKPK 1 Rp 6.500.000
  }
  if (raw.includes('operator-forklift') || raw.includes('forklift')) {
    return pricingList[90]; // Forklift Rp 4.250.000
  }

  // Default fallback
  return {
    title: titleOrSlug,
    days: 3,
    duration: '3 Hari',
    price: 'Rp 4.250.000',
    priceNumber: 4250000,
  };
}
